+__device__ __forceinline__ void for_each_staged_score(const InT* buf,
+                                                      uint32_t sz,
+                                                      Visit visit) {
+  const auto tx = threadIdx.x;
+  if constexpr (std::is_same_v<InT, __nv_bfloat16>) {
+    const auto* words = reinterpret_cast<const uint32_t*>(buf);
+#pragma unroll
